package org.geysermc.paletter.tools.model;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonElement;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * {@code codegen/model/components.json}: the add-on JSON side of every item and block component, as the official
 * creator docs describe it. Generated by {@code spec docs}; never edited by hand (corrections live in
 * {@code codegen/model/errata.json}, applied on load).
 *
 * @param source     where the docs come from (repository and pinned commit)
 * @param license    license of the docs content the model is derived from
 * @param components every component and pseudo component (description, menu_category, states, traits, permutations)
 * @param formatNotes every statement of the docs that ties behaviour to a format version
 */
public record Model(String source, String commit, String license, List<Component> components, List<FormatNote> formatNotes) {
    public static final Gson GSON = new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().create();

    /**
     * @param id        {@code <kind>:<name>}, e.g. {@code item:minecraft:durability}, {@code block:description},
     *                  {@code block:trait:minecraft:placement_direction}
     * @param kind      {@code item} or {@code block}
     * @param category  {@code component}, {@code description}, {@code states}, {@code trait} or {@code permutations}
     * @param status    {@code active} (listed by the docs), {@code deprecated} (listed as internal/deprecated) or
     *                  {@code unlisted} (a page no list links to)
     * @param page      the docs page, relative to the repository
     * @param forms     the JSON types the component value itself may have (an object with {@code fields}, and the
     *                  "alternate simple representations")
     * @param fields    every field below the root, flattened; paths join keys with {@code .}, array elements as
     *                  {@code []}, map values as {@code {}}
     * @param experiments experiment toggles the docs name for the component
     */
    public record Component(String id, String kind, String category, String name, String status, String doc, String page,
                            String minFormatVersion, List<String> experiments, List<JType> forms, List<Field> fields,
                            List<String> notes) {
        public Field field(String path) {
            return fields.stream().filter(f -> f.path().equals(path)).findFirst().orElse(null);
        }

        public boolean hasObjectForm() {
            return forms.stream().anyMatch(f -> f.type().equals("object"));
        }
    }

    /**
     * @param path      path below the component root
     * @param types     the JSON types the docs allow (several when the docs list {@code name (as String)} rows)
     * @param defaultValue the documented default, or null when "not set"
     * @param required  whether the docs call the field required
     * @param enumValues allowed values when the docs enumerate them (choices tables, "valid values are ...")
     * @param range     numeric bounds the docs state in prose
     * @param examples  example values (vanilla content) from the docs, used to pick valid strings
     */
    public record Field(String path, List<JType> types, JsonElement defaultValue, boolean required, List<JsonElement> enumValues,
                        Range range, String minFormatVersion, List<JsonElement> examples, String doc) {
        public String name() {
            String p = path;
            while (p.endsWith("[]") || p.endsWith("{}")) {
                p = p.substring(0, p.length() - 2);
            }
            int dot = p.lastIndexOf('.');
            return dot < 0 ? p : p.substring(dot + 1);
        }

        public boolean has(String type) {
            return types.stream().anyMatch(t -> t.type().equals(type));
        }
    }

    /**
     * @param type  {@code boolean}, {@code integer}, {@code number}, {@code string}, {@code object}, {@code array},
     *              {@code map} (object with free keys), {@code vec3} (array of three numbers) or {@code any}
     * @param items element type of an array or value type of a map
     * @param ref   title of the docs section that describes an object type
     * @param label the docs' label for this alternative (e.g. "Using custom boxes"), if any
     */
    public record JType(String type, JType items, String ref, String label) {
        public static JType of(String type) {
            return new JType(type, null, null, null);
        }

        @Override
        public String toString() {
            return switch (type) {
                case "array" -> "array<" + (items == null ? "any" : items) + ">";
                case "map" -> "map<" + (items == null ? "any" : items) + ">";
                default -> type;
            };
        }
    }

    public record Range(Double min, Double max, String text) {
    }

    /** A docs statement tying behaviour to a format version: {@code version} is the version it names. */
    public record FormatNote(String version, String component, String text) {
    }

    public Component component(String id) {
        return components.stream().filter(c -> c.id().equals(id)).findFirst().orElse(null);
    }

    public static Model read(Path file) throws IOException {
        return GSON.fromJson(Files.readString(file, StandardCharsets.UTF_8), Model.class);
    }

    public void write(Path file) throws IOException {
        Files.createDirectories(file.getParent());
        Files.writeString(file, GSON.toJson(this) + "\n", StandardCharsets.UTF_8);
    }
}
